insert into public.product_content
  (manufacturer, page_key, name, tagline, description, features, clinical_applications,
   options, billing_codes, image, category, sku_count, skus, source_pages, source_files,
   confidence, msrp_rule, status)
values
('ovation-medical', 'gen2-walking-boot', 'Gen 2® Walking Boot', 'The World''s Most Advanced Walker', 'Ovation''s patented Gen 2® Walking Boot has been validated as the most advanced double upright walker on the market by healthcare professionals worldwide. Designed with the patient in mind, our Gen 2® eliminates all of the issues associated with old style walking boots. Lightyears ahead of its competition, the Gen 2® is the best option for your patients.', '["Incredibly light weight and low profile.", "Intuitive Sole allows patients to track naturally with their own gait pattern.", "Shock-Pod feature results in 50% less energy being transferred to the injured limb upon each heel strike.", "Sure-Grip resting surface prevents the limb from slipping when elevated on a smooth surface.", "Sculpted frame accommodates a wide variety of patient anatomies.", "Easy single push-button release system."]'::jsonb, '["Soft tissue injuries", "Grade 2 and 3 sprains / stable fractures", "Post-operative use", "Trauma and rehab"]'::jsonb, '{"Height": ["Tall", "Short"], "Inflation": ["Pneumatic", "Non-Pneumatic"], "Color": ["Blue", "Red", "Black", "Grey"]}'::jsonb, '["L4360", "L4361", "L4386", "L4387"]'::jsonb, '/assets/products/ovation-medical/gen2-walking-boot.png', 'Pneumatic Walkers', 20, '["10002", "10003", "10005", "10007", "10008", "10102", "10103", "10105", "10107", "10108", "11002", "11003", "11005", "11007", "11008", "11102", "11103", "11105", "11107", "11108"]'::jsonb, '4-5', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'nu-form-ankle-brace', 'Nu-Form™ Ankle Brace', 'Exceptional Comfort, Enhanced Stability', 'Our patented Nu-Form™ Ankle Brace combines the best features of a classic lace-up figure-8 with the support of an ankle stirrup into a low-profile, lightweight, and breathable solution. Our Fusion-Form manufacturing process allows us to provide superior support, compression, and comfort that would otherwise not be possible using the conventional cut and sew method.', '["Unique design that blends the support of a stirrup with the comfort and compressive fit of a lace-up.", "Low-profile design fits easily in all shoe categories.", "Multi-layer frame provides superior rotational protection at the mid-foot and inversion/eversion control.", "Even compression manages daily swelling patterns.", "3D spacer fabric allows heat and moisture to escape."]'::jsonb, '["Acute ankle sprains", "Post-operative support", "Ankle injury rehabilitation", "Chronic ankle instability", "Prophylactic use"]'::jsonb, '{"Size": ["X-Small", "Small", "Medium", "Large", "X-Large"]}'::jsonb, '["L1902"]'::jsonb, '/assets/products/ovation-medical/nu-form-ankle-brace.png', 'Ankles', 8, '["25001-2", "25001-2B", "25002-2B", "25003-2B", "25005-2B", "25007-2B", "25008-2B", "25009-2B"]'::jsonb, '6-7, 7', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'lace-up-ankle', 'Lace-Up Ankle Brace', null, null, '["Durable ballistic nylon construction ensures long-lasting use.", "Even compression aids in reducing swelling and promotes healing.", "Figure-8 straps offer precise inversion/eversion control.", "Tibia strap provides additional compression and support.", "Conveniently fits into a shoe for easy and convenient wear."]'::jsonb, '["Acute ankle sprains", "Post-operative support", "Ankle injury rehabilitation", "Chronic ankle instability", "Prophylactic use"]'::jsonb, '{"Size": ["XX-Small", "X-Small", "Small", "Medium", "Large", "X-Large", "XX-Large"]}'::jsonb, '["L1902"]'::jsonb, '/assets/products/ovation-medical/lace-up-ankle.png', 'Ankles', 7, '["25001", "25002", "25003", "25005", "25007", "25008", "25009"]'::jsonb, '8', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'ankle-stirrup', 'Foam Ankle Stirrups', null, null, '["Bilateral shells for rigid support, allowing controlled dorsal and plantar flexion while managing inversion/eversion.", "Breathable low-profile liners and slim design ensure a comfortable fit in shoes.", "Convenient hook and loop closures for quick and secure clinical application.", "Bilateral shells provide rigid support, allowing dorsal and plantar flexion while controlling inversion/eversion.", "Inflatable air bladders provide a comfortable fit and actively reduce edema.", "Hook and loop closures allow for quick and convenient clinical application."]'::jsonb, '["Acute ankle sprains", "Post-operative support", "Ankle injury rehabilitation", "Chronic ankle instability", "Prophylactic use"]'::jsonb, '{"Color": ["Black", "White"], "Size": ["Youth/Universal", "Standard/Universal"]}'::jsonb, '["L4350"]'::jsonb, '/assets/products/ovation-medical/ankle-stirrup.png', 'Ankles', 8, '["2000B", "2000W", "2100B", "2100W", "2020B", "2020W", "2120B", "2120W"]'::jsonb, '9', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'nu-form-back', 'Nu-Form™ Universal Back Brace', 'Unmatched Breathability, Superior Comfort', null, '["Includes a customizable/moldable anterior panel.", "Coverage from L1-L5 for the L0627 and S1-T9 vertebra for the L0631/L0637.", "Completely breathable over the spinous process.", "Pressure relief zone automatically adjusts to provide relief at surgical sites.", "Extremely thin and low-profile, fits comfortably under clothing.", "Designed for both post-op and pain relief.", "Universally sized and easily adjustable.", "Rigid posterior panel automatically adjusts to unique patient anatomy.", "Incredibly durable, backed by a 5-year warranty."]'::jsonb, '["Lumbar Spinal Post-Op Care", "Chronic Lower Back Pain", "Lumbar Sprains and Strains", "Spondylolisthesis", "Osteoporosis", "Fracture Management", "Post-Operative Support", "Non-Specific Low Back Pain"]'::jsonb, '{"Size": ["30\"-48\"", "30\"-70\" (Extension Belt)"]}'::jsonb, '["L0627", "L0642", "L0631", "L0648", "L0637", "L0650"]'::jsonb, '/assets/products/ovation-medical/nu-form-back.png', 'Backs', 4, '["62001", "62002", "62007", "61008-2"]'::jsonb, '20-21', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'ls-double-pull-back', 'Universal LS Double-Pull Back Brace', null, null, '["Includes an anterior panel.", "Coverage from L1-L5 for the L0627 and S1-T9 vertebra for the L0631/L0637.", "Universally sized.", "Easily adjustable straps allow for quick clinical application.", "Double-pull pulley system provides adjustable level of compression.", "Quality materials increase breathability and enhance comfort."]'::jsonb, '["Lumbar Spinal Post-Op Care", "Chronic Lower Back Pain", "Lumbar Sprains and Strains", "Spondylolisthesis", "Osteoporosis", "Fracture Management", "Post-Operative Support", "Non-Specific Low Back Pain"]'::jsonb, '{"Size": ["25\"-50\"", "50\"-60\""]}'::jsonb, '["L0627", "L0631", "L0637"]'::jsonb, '/assets/products/ovation-medical/ls-double-pull-back.png', 'Backs', 26, '["61000-2", "61000-210", "61001", "61003", "61002", "61004", "61007", "61008", "60010", "60013", "60015", "60017", "60018", "60019", "60023", "60025", "60027", "60028", "60029", "60033", "60035", "60037", "60038", "60039", "60067", "60068"]'::jsonb, '22', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'lumbar-support', 'Elastic Lumbar Support', null, null, '["Firm compressible lumbar pad provides optimum support.", "Quality materials increase breathability and enhance comfort.", "Overlapping elastic pull strap design provides lumbar and abdominal support."]'::jsonb, '["Chronic lower back pain", "Lumbar sprains/strains", "Spondylolisthesis", "Osteoporosis"]'::jsonb, '{"Size": ["Small", "Medium", "Large", "XLarge", "XXLarge"]}'::jsonb, '[]'::jsonb, '/assets/products/ovation-medical/lumbar-support.png', 'Backs', 5, '["60003", "60005", "60007", "60008", "60009"]'::jsonb, '23', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'game-changer-oa', 'The Game Changer™ OA Knee Brace', null, null, '["Universal sizing (right or left).", "Single upright design.", "Effectively treats both medial and lateral knee pain.", "Easy push-button release for quick don and doffing."]'::jsonb, '["Moderate to severe compartmental knee osteoarthritis", "Degenerative meniscal tears", "Knee conditions that may benefit from compartmental unloading"]'::jsonb, '{"Side": ["Universal Left", "Universal Right"]}'::jsonb, '["L1843", "L1851"]'::jsonb, '/assets/products/ovation-medical/game-changer-oa.png', 'Game Changer', 5, '["49001", "49002", "4900-OKBU-S-M", "4900-OKBU-L-XL", "4900-Wrap"]'::jsonb, '15', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'neoprene-knee', 'Neoprene Knee Support with Stabilized Patella', null, null, '["Universal buttress provides patellar control.", "Spiral stays for medial and lateral support.", "Breathable and low-profile design.", "Hinged medial/lateral stays provide support and control range of motion.", "Front hook and loop closures for quick clinical application.", "Anterior wraparound style accommodates all leg shape variations."]'::jsonb, '["Mild or moderate ligament joint pain", "Pain and sprains in the knee", "Compression and support reduce knee instability"]'::jsonb, '{"Size": ["Small", "Medium", "Large", "X-Large", "XX-Large", "3X-Large", "4X-Large"]}'::jsonb, '["L1810", "L1812"]'::jsonb, '/assets/products/ovation-medical/neoprene-knee.png', 'Knee Supports', 17, '["45003", "45005", "45007", "45008", "45009", "45013", "45015", "45017", "45018", "45019", "45023", "45025", "45027", "45028", "45029", "45030", "45031"]'::jsonb, '16, 17', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'compact-pro-rom', 'Compact Pro ROM Post-Op Knee Brace', null, null, '["Telescoping struts for length adjustment from 17\"-29\".", "Simple rotate and release flexion/extension settings.", "Unique safety lock feature for increased patient compliance.", "100% tool-free adjustments.", "Drop lock button.", "Quickly locks at 0\u00b0, 10\u00b0, 20\u00b0, 30\u00b0, 45\u00b0, 60\u00b0, 75\u00b0 & 90\u00b0."]'::jsonb, '["ACL, PCL, MCL, and LCL knee-related repairs", "Tibia fractures", "Meniscal repairs", "Patella tendon repairs", "Condylar fractures", "Severe knee pain or stiffness", "Chronic knee inflammation and swelling"]'::jsonb, '{"Size": ["Standard", "X-Large"], "Wrap": ["Standard Wrap", "Cool Wrap"]}'::jsonb, '["L1832", "L1833"]'::jsonb, '/assets/products/ovation-medical/compact-pro-rom.png', 'Post Op Knee', 4, '["51500", "51508", "51600", "51608"]'::jsonb, '16', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'hybrid-night-splint', 'Hybrid Night Splint', 'The Best of Both Worlds', 'Traditionally, orthopedic bracing companies have provided only two night splint options for treating plantar fasciitis and heel pain. These offerings have led to frustrated doctors, non-compliant patients, and huge gaps in recovery outcomes. Ovation''s patented Hybrid Night Splint offers more comfort than a posterior splint and better functionality than a dorsal, making it the best of both worlds.', '["Allows patients with severe heel pain to start at less than 90-degrees.", "Articulating hinge lets patients adjust the level of stretch over time.", "Holds foot securely in place without giving up comfort or mobility.", "Position (stretch) indicator window lets patients participate in their own rehab process.", "Footbed is over 40% wider than a dorsal splint, preventing toe binding."]'::jsonb, '["Plantar Fasciitis", "Achilles Tendonitis", "Heel Pain", "Drop Foot", "Post-Static Pain"]'::jsonb, '{"Size": ["Small to Medium", "Large to X-Large"]}'::jsonb, '["L4397"]'::jsonb, '/assets/products/ovation-medical/hybrid-night-splint.png', 'Night Splints', 3, '["30014", "30016", "30000S"]'::jsonb, '10-11', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'night-splint', 'Posterior Night Splint', null, null, '["Bilateral straps easily adjust flexion, providing a comfortable and gradual stretch of the Plantar Fascia and Achilles Tendon.", "Dorsi-flexion can be adjusted off of 90\u00b0, allowing for a customized range of motion.", "Soft lined interior is breathable, comfortable, and washable.", "Straps are padded for comfort across the dorsum of the ankle.", "Easy-release buckles are simple to use.", "Padded shell holds the foot at a 90-degree angle, providing optimal support and promoting proper healing.", "Lightweight, low-profile dorsal design allows for easy application and improved compliance."]'::jsonb, '["Plantar fasciitis", "Achilles tendonitis", "Drop foot", "Heel pain", "Post-static pain"]'::jsonb, '{"Size": ["Small", "Medium", "Large", "Small to Medium", "Large to X-Large"]}'::jsonb, '["L4397", "L4398"]'::jsonb, '/assets/products/ovation-medical/night-splint.png', 'Night Splints', 8, '["31003", "31005", "31007", "22003", "22005", "22007", "30004", "30006"]'::jsonb, '12', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'versa-fit-wrist', 'Versa-Fit™ Wrist Brace', 'Biggest improvement to the wrist & thumb category in over 20 years', 'Our patented Versa-Fit™ Wrist Brace and Versa-Fit™ Thumb Spica are the first off-the-shelf, custom fitting wrist & thumb supports. Powered by our patented Versa-Fit™ technology, the standard size fits over 90% of people, allowing you to free up shelf space and carry less product.', '["Standard size fits virtually all patients, reducing need to carry excess inventory.", "Versa-Fit\u2122 Flex Panel automatically expands, providing a custom off-the-shelf fit.", "Auto-lock strap secures custom sizing.", "Cut low at the palmar crease to allow for 90-degree MP flexion.", "Standard size fits virtually all patients.", "Custom off-the-shelf fit.", "Neutral thumb position allows opposition.", "Auto-lock strap secures sizing."]'::jsonb, '["Carpal tunnel", "Incomplete fractures", "Tendonitis", "Soft tissue injuries", "Post-cast support for healing", "Gamekeeper''s thumb", "Dequervain''s tendonitis", "Scaphoid injuries"]'::jsonb, '{"Size": ["X-Small", "Standard", "X-Large"], "Side": ["Right", "Left"]}'::jsonb, '["L3908", "L3809"]'::jsonb, '/assets/products/ovation-medical/versa-fit-wrist.png', 'Thumbs', 18, '["50072-5", "50075-5", "50078-5", "51072-5", "51075-5", "51078-5", "50072-2", "50075-2", "50078-2", "51072-2", "51075-2", "51078-2", "58072-2", "58075-2", "58078-2", "59072-2", "59075-2", "59078-2"]'::jsonb, '25', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'thumb-spica', 'Nu-Form™ Thumb Spica', null, null, '["Standard size fits virtually all patients.", "Flex panel allows for custom off-the-shelf fit.", "Flagless design enables 100% capture of the thumb.", "Adjustable radial and volar stays.", "Non-porous material minimizes moisture and dirt retention.", "Breathable, minimal irritation.", "One-hand, effortless fastening.", "Malleable and palmar stays for tailored rehab.", "Universal fit reduces inventory needs.", "Low-profile for easy compliance.", "Natural hand & thumb motion."]'::jsonb, '["Incomplete fractures", "Tendonitis", "Soft tissue injuries", "Post-cast support for healing", "Gamekeeper''s thumb", "Dequervain''s tendonitis", "Scaphoid injuries"]'::jsonb, '{"Size": ["X-Small", "Standard", "X-Large"], "Side": ["Right", "Left"]}'::jsonb, '["L3809"]'::jsonb, '/assets/products/ovation-medical/thumb-spica.png', 'Thumbs', 12, '["50072", "50073", "50075", "50077", "50078", "51072", "51073", "51075", "51077", "51078", "50070", "51070"]'::jsonb, '24, 27', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'universal-wrist', 'Universal 8" Wrist Brace', null, null, '["Breathable for all-day comfort.", "Tailored recovery with malleable stays.", "One-size-fits-most, minimizes inventory.", "One-pull, one-hand easy fastening.", "Customizable palmar stability."]'::jsonb, '["Carpal tunnel", "Incomplete fractures", "Tendonitis", "Soft tissue injuries", "Post-cast support for healing"]'::jsonb, '{"Side": ["Right", "Left"]}'::jsonb, '["L3908"]'::jsonb, '/assets/products/ovation-medical/universal-wrist.png', 'Wrists', 12, '["58072", "58073", "58075", "58077", "58078", "59072", "59073", "59075", "59077", "59078", "58070", "59070"]'::jsonb, '27', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
('ovation-medical', 'post-op-shoe', 'Ovation Square Toe Post-Op Shoe', null, null, '["Extended rocker sole is both rigid and durable.", "High ankle strap to allow for proper fit.", "Removable insole accommodates for additional dressings and swelling.", "Unisex (fits both men and women).", "Breathable Mesh Upper.", "Reinforced Heel Counter and Support.", "Sole materials reduce sliding.", "Cushioned rocker bottom design.", "Open toe and heel for extra comfort.", "Features easy contact closure."]'::jsonb, '["Broken toes", "Metatarsal fractures", "Foot and ankle sprains", "Broken Toes", "Metatarsal Fractures", "Foot and Ankle Sprains"]'::jsonb, '{"Size": ["X-Small", "Small", "Medium", "Large", "X-Large", "Small/Medium", "Medium/Large"]}'::jsonb, '[]'::jsonb, '/assets/products/ovation-medical/post-op-shoe.png', 'Cast & Post Op Shoes', 15, '["701XS", "701MS", "701MM", "701ML", "701MXL", "701WS", "701WM", "701WL", "702ML", "702MM", "702MS", "702MXL", "702WL", "702WM", "702WS"]'::jsonb, '13, 14', '["Ovation_Medical_Coded_Product_Catalog_2026.pdf", "Ovation_Medical_Retail_Catalog_2026.pdf"]'::jsonb, 0.93, 'single_unit_x2', 'pending_review'),
